args.command:
node -e '
// Test continuous ramp curve and 6-DOF rigid body stunt physics
const DEG = Math.PI / 180;
const LIP_ANGLE = 115 * DEG; // 2.0071286 rad

// Build ramp lookup table
const N = 400;
const rawU = [], rawTheta = [], rawX = [0], rawY = [0];
for (let i = 0; i <= N; i++) {
  const u = i / N;
  rawU.push(u);
  // Smooth C2 monotonic curve: theta(0)=0, theta"(0)=0, theta(1)=115 deg
  const th = LIP_ANGLE * (1.42 * Math.pow(u, 1.55) - 0.42 * Math.pow(u, 2.55));
  rawTheta.push(th);
  if (i > 0) {
    const du = 1 / N;
    const thMid = 0.5 * (rawTheta[i - 1] + th);
    rawX.push(rawX[i - 1] + Math.cos(thMid) * du);
    rawY.push(rawY[i - 1] + Math.sin(thMid) * du);
  }
}
const totalLength = 20.0 / rawY[N];
console.log("Ramp arc length L =", totalLength.toFixed(2), "m, lip X =", (rawX[N]*totalLength).toFixed(2), "m, lip Y =", (rawY[N]*totalLength).toFixed(2), "m, max X =", (Math.max(...rawX)*totalLength).toFixed(2), "m");
'

