    // Controller state machine
    let driveForceCmd = 0;
    let brakeCmd = 0;
    let fanThrottle = 0;
    const thrust = { LIFT_FL:0, LIFT_FR:0, LIFT_RL:0, LIFT_RR:0, ROLL_L:0, ROLL_R:0, PITCH_NOSE:0, PITCH_TAIL:0, REAR_L:0, REAR_R:0 };

    if (phase === "READY") {
      brakeCmd = 1.0;
      if (t >= 0.5) phase = "CLIMB";
    } else if (phase === "CLIMB") {
      fanThrottle = rp.theta > 0.2 ? 1.0 : Math.min(1.0, Math.max(0.2, (pos[0] + 2) * 0.25));
      const targetS = ramp.L - 2.45; // stop near lip where theta ~ 112.5 deg
