        phase = "SLIDING_BACK";
      } else {
        const vErr = vTarget - tangVel;
        if (vErr > 0) {
          driveForceCmd = Math.min(1.0, vErr * 0.45) * 44000 * drivePowerScale;
        } else {
          brakeCmd = Math.min(1.0, -vErr * 0.55);
        }
      }
    } else if (phase === "HOLD_INVERTED") {
      fanThrottle = 1.0;
      brakeCmd = 1.0;
      holdTimer += dt;
      // Hold position on overhang using tire brake + creep trim
      const targetS = ramp.L - 2.35;
      const sErr = targetS - rp.s;
      const tangVel = vel[0] * rp.tx + vel[1] * rp.ty;
      driveForceCmd = (sErr * 18000 - tangVel * 22000);
      if (holdTimer > 1.75) {
        thrust.PITCH_TAIL = 0.22;
