          rErr = -2.8;
        }
        const rollTorqueCmd = rErr * 2.4 - omegaBody[0] * 0.75;
        if (rollTorqueCmd > 0) {
          thrust.ROLL_L = Math.min(1, rollTorqueCmd);
          thrust.LIFT_FL = Math.min(0.7, rollTorqueCmd * 0.5);
          thrust.LIFT_RL = Math.min(0.7, rollTorqueCmd * 0.5);
        } else {
          thrust.ROLL_R = Math.min(1, -rollTorqueCmd);
          thrust.LIFT_FR = Math.min(0.7, -rollTorqueCmd * 0.5);
          thrust.LIFT_RR = Math.min(0.7, -rollTorqueCmd * 0.5);
        }

        // Pitch stabilization (keep xAxis[1] -> 0)
        const pitchCmd = -pitchErrorFromHorizMinusX * 3.2 - omegaBody[2] * 0.85;
        if (pitchCmd > 0) {
