          thrust.LIFT_FL = Math.min(0.7, rollTorqueCmd * 0.5);
          thrust.LIFT_RL = Math.min(0.7, rollTorqueCmd * 0.5);
        } else {
          thrust.ROLL_R = Math.min(1, -rollTorqueCmd);
          thrust.LIFT_FR = Math.min(0.7, -rollTorqueCmd * 0.5);
          thrust.LIFT_RR = Math.min(0.7, -rollTorqueCmd * 0.5);
