          const targetVy = pos[1] > 2.4 ? -Math.min(10.0, Math.sqrt(2 * 6.2 * Math.max(0, pos[1] - 1.55)) + 0.8) : (pos[1] > 0.85 ? -1.1 : -0.6);
          const vyErr = targetVy - vel[1];
          const baseLift = Math.max(0, Math.min(1.0, (mass * g + vyErr * mass * 5.2) / (totalThrusterN * 0.72 || 1)));
