          thrust.LIFT_FR = Math.min(1.0, thrust.LIFT_FR + baseLift * 0.9);
          thrust.LIFT_RL = Math.min(1.0, thrust.LIFT_RL + baseLift * 0.9);
          thrust.LIFT_RR = Math.min(1.0, thrust.LIFT_RR + baseLift * 0.9);
