          n = [wrp.nx, wrp.ny, 0];
        }
      }
      const restDist = 0.42;
      const align = dot(yAxis, n);
      if (dSurf < restDist && align > 0.25) {
        const comp = restDist - dSurf;
        w.comp = Math.min(0.28, comp);
        const vn = dot(wVel, n);
        const Fn = Math.max(0, kSpring * comp - kDamp * vn);
        totalWheelNormalF += Fn;
        if (-vn > 5.0) {
          maxImpactImpulse = Math.max(maxImpactImpulse, -vn * mass * 0.35);
        }

        // Tangential forward & lateral directions on surface
        let tLong = [
          xAxis[0] - dot(xAxis, n)*n[0],
          xAxis[1] - dot(xAxis, n)*n[1],
          xAxis[2] - dot(xAxis, n)*n[2]
        ];
        const tlLen = Math.hypot(tLong[0], tLong[1], tLong[2]) || 1;
        tLong = [tLong[0]/tlLen, tLong[1]/tlLen, tLong[2]/tlLen];

        let tLat = cross(n, tLong);
        const vLong = dot(wVel, tLong);
        const vLat = dot(wVel, tLat);

        let fLong = (driveForceCmd * 0.25) - brakeCmd * vLong * (mass * 4.5);
        let fLat = -vLat * (mass * 6.0) - wPos[2] * (mass * 2.5);

        const maxGrip = 1.42 * Fn;
        const fTangMag = Math.hypot(fLong, fLat);
        if (fTangMag > maxGrip && fTangMag > 1e-5) {
          fLong *= maxGrip / fTangMag;
          fLat *= maxGrip / fTangMag;
        }

        const Fw = [
          n[0]*Fn + tLong[0]*fLong + tLat[0]*fLat,
          n[1]*Fn + tLong[1]*fLong + tLat[1]*fLat,
          n[2]*Fn + tLong[2]*fLong + tLat[2]*fLat
        ];
        F[0] += Fw[0]; F[1] += Fw[1]; F[2] += Fw[2];
        const FwBody = quatRotate(quatConj(quat), Fw);
        const tW = cross(w.r, FwBody);
        tauBody[0] += tW[0]; tauBody[1] += tW[1]; tauBody[2] += tW[2];
      } else {
        w.comp = 0;
      }
    }

    if (phase === "CLIMB" && rp.theta > 70 * DEG) {
      minWallNormalF = Math.min(minWallNormalF, totalWheelNormalF);
      if (totalWheelNormalF < 100 && distToRamp > 0.75) {
        phase = "FELL_OFF_RAMP";
      }
    }

    // Apply Cold-Gas Thrusters at exact nozzle positions!
    const perNozzleMax = totalThrusterN * 0.22;
    for (const [k, frac] of Object.entries(thrust)) {
      if (frac > 0.001 && perNozzleMax > 0) {
        const nz = nozzles[k];
        const fMag = Math.min(1, frac) * perNozzleMax;
        const fBody = [nz.fDir[0] * fMag, nz.fDir[1] * fMag, nz.fDir[2] * fMag];
        const fWorld = quatRotate(quat, fBody);
        F[0] += fWorld[0]; F[1] += fWorld[1]; F[2] += fWorld[2];
        const tNz = cross(nz.r, fBody);
        tauBody[0] += tNz[0]; tauBody[1] += tNz[1]; tauBody[2] += tNz[2];
      }
    }

    // Chassis collision with ground/ramp (for inverted/sideways/hard crashes)
    if (pos[1] < 0.36) {
      const pen = 0.36 - pos[1];
      const impactVn = -vel[1];
      if (impactVn > 4.5 || yAxis[1] < 0.3) {
        maxImpactImpulse = Math.max(maxImpactImpulse, Math.max(impactVn, 3.0) * mass * (yAxis[1] < 0.3 ? 1.2 : 0.6));
      }
      const fnChassis = mass * 90 * pen + Math.max(0, -vel[1]) * mass * 12;
      F[1] += fnChassis;
      F[0] -= vel[0] * mass * 3.5;
    }

    // Integrate linear velocity & position
    vel[0] += (F[0] / mass) * dt;
    vel[1] += (F[1] / mass) * dt;
    vel[2] += (F[2] / mass) * dt;
    pos[0] += vel[0] * dt;
    pos[1] += vel[1] * dt;
    pos[2] += vel[2] * dt;

    // Integrate angular velocity in body frame (Euler equations)
    const Iw = [Ibody[0]*omegaBody[0], Ibody[1]*omegaBody[1], Ibody[2]*omegaBody[2]];
    const gyro = cross(omegaBody, Iw);
    omegaBody[0] += ((tauBody[0] - gyro[0]) / Ibody[0]) * dt;
    omegaBody[1] += ((tauBody[1] - gyro[1]) / Ibody[1]) * dt;
    omegaBody[2] += ((tauBody[2] - gyro[2]) / Ibody[2]) * dt;
    omegaBody[0] *= 0.996;
    omegaBody[1] *= 0.992;
    omegaBody[2] *= 0.996;

    const dq = quatMul(quat, [omegaBody[0]*0.5*dt, omegaBody[1]*0.5*dt, omegaBody[2]*0.5*dt, 0]);
    quat = quatNormalize([quat[0]+dq[0], quat[1]+dq[1], quat[2]+dq[2], quat[3]+dq[3]]);

    if (step % 120 === 0 || (step % 30 === 0 && (phase === "RELEASE_AND_ROLL" || phase === "HOLD_INVERTED"))) {
      console.log(`t=${t.toFixed(2)}s [${phase}] pos=(${pos[0].toFixed(1)}, ${pos[1].toFixed(1)}) vel=(${vel[0].toFixed(1)}, ${vel[1].toFixed(1)}) yUp=${yAxis[1].toFixed(2)} xUp=${xAxis[1].toFixed(2)}`);
    }
  }
  console.log("Final summary:", { phase, maxImpactImpulse: Math.round(maxImpactImpulse), minWallNormalF: Math.round(minWallNormalF), finalPos: pos.map(v => +v.toFixed(2)) });
}

console.log("=== DEFAULT STUNT ===");
runSim({});
