      // Then a 180-deg ROLL around local X-axis rotates yAxis from [0, -1, 0] -> [0, +1, 0] (wheels-down!) and zAxis from [0, 0, 1] -> [0, 0, -1]!
      const pitchErrorFromHorizMinusX = Math.asin(Math.max(-1, Math.min(1, xAxis[1]))); // + when nose points up (+Y)
