      }
    }

    // Accumulate forces and torques
    let F = [0, -mass * g, 0];
    let tauBody = [0, 0, 0];

    // Aerodynamic drag
    const speed = Math.hypot(vel[0], vel[1], vel[2]);
    const drag = 0.42 * speed;
    F[0] -= drag * vel[0];
    F[1] -= drag * vel[1];
    F[2] -= drag * vel[2];

