      surfNormal = [rp.nx, rp.ny, 0];
      surfTang = [rp.tx, rp.ty, 0];
    }
    const fanProx = Math.max(0, Math.min(1, 1.35 - surfaceDist));
    const fanForceMag = fanThrottle * (maxFanKgf * 9.81) * (0.12 + 0.88 * fanProx);
