        if (yAxis[1] > 0.25) {
          // Hover briefly around y = 1.6m, then descend gently
          let targetVy = -2.0;
          if (pos[1] > 2.2) {
            targetVy = -Math.min(11.0, Math.sqrt(2 * 6.8 * (pos[1] - 1.7)) + 1.1);
          } else if (pos[1] > 1.15 && releaseTimer < 2.65) {
            targetVy = (1.55 - pos[1]) * 2.5; // brief low hover at y ~ 1.55m!
