const DEG = Math.PI / 180;
const RAD = 180 / Math.PI;
const LIP_ANGLE = 115 * DEG;

class RampCurve {
  constructor() {
    this.N = 500;
    this.sArr = new Float64Array(this.N + 1);
    this.xArr = new Float64Array(this.N + 1);
    this.yArr = new Float64Array(this.N + 1);
    this.thArr = new Float64Array(this.N + 1);
    this.kArr = new Float64Array(this.N + 1);
    const rawX = [0], rawY = [0], rawTh = [0];
    for (let i = 1; i <= this.N; i++) {
      const u = i / this.N;
      const th = LIP_ANGLE * (1.42 * Math.pow(u, 1.55) - 0.42 * Math.pow(u, 2.55));
      rawTh.push(th);
      const du = 1 / this.N;
      const thMid = 0.5 * (rawTh[i - 1] + th);
      rawX.push(rawX[i - 1] + Math.cos(thMid) * du);
      rawY.push(rawY[i - 1] + Math.sin(thMid) * du);
    }
    this.L = 20.0 / rawY[this.N];
    this.width = 5.4;
    for (let i = 0; i <= this.N; i++) {
      const u = i / this.N;
      this.sArr[i] = u * this.L;
      this.xArr[i] = rawX[i] * this.L;
      this.yArr[i] = rawY[i] * this.L;
      this.thArr[i] = rawTh[i];
      const dth_du = LIP_ANGLE * (1.42 * 1.55 * Math.pow(Math.max(u, 1e-4), 0.55) - 0.42 * 2.55 * Math.pow(u, 1.55));
      this.kArr[i] = (i === 0) ? 0 : dth_du / this.L;
    }
  }
  sample(s) {
    if (s <= 0) {
      return { s, x: s, y: 0, theta: 0, kappa: 0, tx: 1, ty: 0, nx: 0, ny: 1 };
    }
    const sc = Math.min(this.L, s);
    const u = sc / this.L;
    const idx = u * this.N;
    const i0 = Math.min(this.N - 1, Math.floor(idx));
    const f = idx - i0;
    const x = this.xArr[i0] + (this.xArr[i0 + 1] - this.xArr[i0]) * f;
    const y = this.yArr[i0] + (this.yArr[i0 + 1] - this.yArr[i0]) * f;
    const th = this.thArr[i0] + (this.thArr[i0 + 1] - this.thArr[i0]) * f;
    const k = this.kArr[i0] + (this.kArr[i0 + 1] - this.kArr[i0]) * f;
    return {
      s: sc, x, y, theta: th, kappa: k,
      tx: Math.cos(th), ty: Math.sin(th),
      nx: -Math.sin(th), ny: Math.cos(th)
    };
  }
  closestRampPoint(px, py) {
    let bestS = 0, bestD2 = Infinity;
    for (let i = 0; i <= this.N; i += 4) {
      const dx = px - this.xArr[i];
      const dy = py - this.yArr[i];
      const d2 = dx * dx + dy * dy;
      if (d2 < bestD2) { bestD2 = d2; bestS = this.sArr[i]; }
    }
    for (let iter = 0; iter < 4; iter++) {
      const pt = this.sample(bestS);
      const dx = px - pt.x, dy = py - pt.y;
      const ds = dx * pt.tx + dy * pt.ty;
      bestS = Math.max(0, Math.min(this.L, bestS + ds));
    }
    return this.sample(bestS);
  }
}

function quatRotate(q, v) {
  const x = v[0], y = v[1], z = v[2];
  const qx = q[0], qy = q[1], qz = q[2], qw = q[3];
  const ix = qw * x + qy * z - qz * y;
  const iy = qw * y + qz * x - qx * z;
  const iz = qw * z + qx * y - qy * x;
  const iw = -qx * x - qy * y - qz * z;
  return [
    ix * qw + iw * -qx + iy * -qz - iz * -qy,
    iy * qw + iw * -qy + iz * -qx - ix * -qz,
    iz * qw + iw * -qz + ix * -qy - iy * -qx
  ];
}
function quatConj(q) { return [-q[0], -q[1], -q[2], q[3]]; }
function quatMul(a, b) {
  return [
    a[3]*b[0] + a[0]*b[3] + a[1]*b[2] - a[2]*b[1],
    a[3]*b[1] - a[0]*b[2] + a[1]*b[3] + a[2]*b[0],
    a[3]*b[2] + a[0]*b[1] - a[1]*b[0] + a[2]*b[3],
    a[3]*b[3] - a[0]*b[0] - a[1]*b[1] - a[2]*b[2]
  ];
}
function quatNormalize(q) {
  const l = Math.hypot(q[0], q[1], q[2], q[3]) || 1;
  return [q[0]/l, q[1]/l, q[2]/l, q[3]/l];
}
function cross(a, b) {
  return [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]];
}
function dot(a, b) { return a[0]*b[0]+a[1]*b[1]+a[2]*b[2]; }

const ramp = new RampCurve();

function runSim(cfg, verbose = true) {
  const mass = cfg.mass ?? 2000;
  const maxFanKgf = cfg.maxFanKgf ?? 4700;
  const drivePowerScale = cfg.drivePower ?? 1.0;
