      const tangVel = vel[0] * rp.tx + vel[1] * rp.ty;
      const gravComp = mass * g * Math.sin(rp.theta);
      driveForceCmd = Math.max(-maxMotorForce, Math.min(maxMotorForce, gravComp + sErr * 25000 - tangVel * 25000));
      if (holdTimer > 1.75) {
        thrust.PITCH_TAIL = 0.25;
      }
      if (holdTimer >= 2.0) {
        phase = "RELEASE_AND_ROLL";
        releaseTimer = 0;
      }
    } else if (phase === "RELEASE_AND_ROLL") {
      releaseTimer += dt;
      fanThrottle = 0;

      const pitchErrorFromHorizMinusX = Math.asin(Math.max(-1, Math.min(1, xAxis[1])));
      const rollAngle = Math.atan2(zAxis[1], yAxis[1]);

      if (releaseTimer < 0.42) {
        // Push clear of ramp & pitch to horizontal belly-up (xAxis -> [-1, 0, 0], yAxis -> [0, -1, 0])
        thrust.PITCH_TAIL = 1.0;
        thrust.LIFT_RL = 0.75;
        thrust.LIFT_RR = 0.75;
        thrust.REAR_L = 0.85;
        thrust.REAR_R = 0.85;
      } else {
        // Roll 180 deg around longitudinal X-axis to wheels-down (yAxis -> [0, +1, 0])
        let rErr = -rollAngle;
        if (yAxis[1] < -0.15 && Math.abs(rollAngle) > 2.0) {
          rErr = -2.8;
        }
        const rollCmd = rErr * 1.8 - omegaBody[0] * 0.52;
        if (rollCmd > 0) {
          thrust.ROLL_L = Math.min(1.0, rollCmd);
          thrust.LIFT_FL = Math.min(0.65, rollCmd * 0.45);
          thrust.LIFT_RL = Math.min(0.65, rollCmd * 0.45);
        } else {
          thrust.ROLL_R = Math.min(1.0, -rollCmd);
          thrust.LIFT_FR = Math.min(0.65, -rollCmd * 0.45);
          thrust.LIFT_RR = Math.min(0.65, -rollCmd * 0.45);
        }

        // Pitch stabilization (keep nose level facing -X: when upright yAxis[1]>0, positive wz pitches nose DOWN if facing -X? Wait!)
        // Let us check in body frame: +wz is rotation around body +Z (from +X toward +Y)!
        // Regardless of world orientation, +wz ALWAYS rotates body +X toward body +Y!
        // So if body +Y is pointing UP (yAxis[1] > 0), +wz pitches the nose UP (+xAxis[1] increases)!
        // If body +Y is pointing DOWN (yAxis[1] < 0, belly-up), +wz pitches the nose DOWN (+xAxis[1] decreases)!
        // That is why body-frame pitch control should multiply by sign(yAxis[1]) or project desired world pitch rate onto zAxis!
        const desiredNoseUpRate = -pitchErrorFromHorizMinusX * 4.5;
        // Wait: in world frame, rotating +X toward world +Y is rotation around cross(xAxis, [0,1,0])!
        const worldPitchAxis = cross(xAxis, [0, 1, 0]);
        const targetWz = dot(worldPitchAxis, zAxis) * desiredNoseUpRate;
        const wzErr = targetWz - omegaBody[2];
        // PITCH_NOSE has r.x = +1.90, fDir.y = +1.0 -> cross(r, F).z = +1.90 > 0 (+wz torque!)
        // PITCH_TAIL has r.x = -1.95, fDir.y = +0.968 -> cross(r, F).z = -1.89 < 0 (-wz torque!)
        if (wzErr > 0) {
          thrust.PITCH_NOSE = Math.min(0.85, wzErr * 0.45);
        } else {
          thrust.PITCH_TAIL = Math.min(0.85, -wzErr * 0.45);
        }

        // Downward braking jets once car has rolled past 90 deg toward wheels-down (yAxis[1] > 0.25)
        if (yAxis[1] > 0.25) {
          // Hover briefly around y = 1.6m, then descend gently
          let targetVy = -2.0;
          if (pos[1] > 2.2) {
            targetVy = -Math.min(11.0, Math.sqrt(2 * 6.8 * (pos[1] - 1.7)) + 1.1);
          } else if (pos[1] > 1.15 && releaseTimer < 2.65) {
            targetVy = (1.55 - pos[1]) * 2.5; // brief low hover at y ~ 1.55m!
          } else {
            targetVy = -1.15; // gentle touchdown descent
          }
          const vyErr = targetVy - vel[1];
          const neededUpForce = Math.max(0, mass * (g + vyErr * 5.8) / Math.max(0.5, yAxis[1]));
          const perCornerMax = totalThrusterN * 0.22;
          const baseLift = perCornerMax > 0 ? Math.min(1.0, neededUpForce / (4 * perCornerMax)) : 0;
          // Distribute across 4 corner nozzles with pitch & roll trim!
          const pitchTrim = Math.max(-0.28, Math.min(0.28, wzErr * 0.14));
          const rollTrim = Math.max(-0.28, Math.min(0.28, rollCmd * 0.14));
          thrust.LIFT_FL = Math.max(0, Math.min(1, baseLift + pitchTrim + rollTrim));
          thrust.LIFT_FR = Math.max(0, Math.min(1, baseLift + pitchTrim - rollTrim));
          thrust.LIFT_RL = Math.max(0, Math.min(1, baseLift - pitchTrim + rollTrim));
          thrust.LIFT_RR = Math.max(0, Math.min(1, baseLift - pitchTrim - rollTrim));
        }
      }

      if (pos[1] <= 0.46 && yAxis[1] > 0.85 && releaseTimer > 1.5) {
        phase = "DRIVE_OUT";
        landTimer = 0;
      }
    } else if (phase === "DRIVE_OUT") {
      landTimer += dt;
      fanThrottle = 0.3;
      if (landTimer < 2.2) {
        driveForceCmd = 22000 * drivePowerScale;
      } else {
        brakeCmd = 0.9;
        if (Math.hypot(vel[0], vel[2]) < 0.25 && landTimer > 2.8) {
          phase = "COMPLETE";
        }
      }
    } else if (phase === "COMPLETE") {
      brakeCmd = 1.0;
    }

    // Forces & torques
    let F = [0, -mass * g, 0];
    let tauBody = [0, 0, 0];

    const speed = Math.hypot(vel[0], vel[1], vel[2]);
    const drag = 0.42 * speed;
    F[0] -= drag * vel[0]; F[1] -= drag * vel[1]; F[2] -= drag * vel[2];

    let surfaceDist = pos[1] - 0.38;
    if (onRampRange && (pos[0] > 0 || rp.s > 0.05)) {
      surfaceDist = distToRamp - 0.38;
    }
    const fanProx = Math.max(0, Math.min(1, (1.15 - surfaceDist) / 0.95));
    const fanForceMag = fanThrottle * (maxFanKgf * 9.81) * (0.08 + 0.92 * fanProx * fanProx);
    F[0] -= yAxis[0] * fanForceMag;
    F[1] -= yAxis[1] * fanForceMag;
    F[2] -= yAxis[2] * fanForceMag;

    const kSpring = mass * 36;
    const kDamp = mass * 5.5;
    let totalWheelNormalF = 0;

    for (let w of wheels) {
      const wPos = [
        pos[0] + xAxis[0]*w.r[0] + yAxis[0]*w.r[1] + zAxis[0]*w.r[2],
        pos[1] + xAxis[1]*w.r[0] + yAxis[1]*w.r[1] + zAxis[1]*w.r[2],
        pos[2] + xAxis[2]*w.r[0] + yAxis[2]*w.r[1] + zAxis[2]*w.r[2]
      ];
      const wRotVel = quatRotate(quat, cross(omegaBody, w.r));
      const wVel = [vel[0] + wRotVel[0], vel[1] + wRotVel[1], vel[2] + wRotVel[2]];

      const wrp = ramp.closestRampPoint(wPos[0], wPos[1]);
      const dRamp = (wPos[0] - wrp.x) * wrp.nx + (wPos[1] - wrp.y) * wrp.ny;
      const dGround = wPos[1];
      let dSurf = dGround, n = [0, 1, 0];
      if (wPos[0] > 0.05 && wrp.s > 0 && wrp.s <= ramp.L && Math.abs(wPos[2]) < 2.65 && dRamp > -0.25 && dRamp < 1.1) {
        if (wPos[1] > 0.6 || dRamp < dGround) {
          dSurf = dRamp;
          n = [wrp.nx, wrp.ny, 0];
        }
      }
      const restDist = 0.42;
      const align = dot(yAxis, n);
      if (dSurf < restDist && align > 0.25) {
        const comp = restDist - dSurf;
        w.comp = Math.min(0.28, comp);
        const vn = dot(wVel, n);
        const Fn = Math.max(0, kSpring * comp - kDamp * vn);
        totalWheelNormalF += Fn;
        if (-vn > 5.5) {
          maxImpactImpulse = Math.max(maxImpactImpulse, -vn * mass * 0.35);
        }

        let tLong = [
          xAxis[0] - dot(xAxis, n)*n[0],
          xAxis[1] - dot(xAxis, n)*n[1],
          xAxis[2] - dot(xAxis, n)*n[2]
        ];
        const tlLen = Math.hypot(tLong[0], tLong[1], tLong[2]) || 1;
        tLong = [tLong[0]/tlLen, tLong[1]/tlLen, tLong[2]/tlLen];

        let tLat = cross(n, tLong);
        const vLong = dot(wVel, tLong);
        const vLat = dot(wVel, tLat);

        let fLong = (driveForceCmd * 0.25) - brakeCmd * vLong * (mass * 4.5);
        let fLat = -vLat * (mass * 6.0) - wPos[2] * (mass * 2.5);

        const maxGrip = 1.42 * Fn;
        const fTangMag = Math.hypot(fLong, fLat);
        if (fTangMag > maxGrip && fTangMag > 1e-5) {
          fLong *= maxGrip / fTangMag;
          fLat *= maxGrip / fTangMag;
        }

        const Fw = [
          n[0]*Fn + tLong[0]*fLong + tLat[0]*fLat,
          n[1]*Fn + tLong[1]*fLong + tLat[1]*fLat,
          n[2]*Fn + tLong[2]*fLong + tLat[2]*fLat
        ];
        F[0] += Fw[0]; F[1] += Fw[1]; F[2] += Fw[2];
        const FwBody = quatRotate(quatConj(quat), Fw);
        const tW = cross(w.r, FwBody);
        tauBody[0] += tW[0]; tauBody[1] += tW[1]; tauBody[2] += tW[2];
      } else {
        w.comp = 0;
      }
    }

    if ((phase === "CLIMB" || phase === "HOLD_INVERTED") && rp.theta > 65 * DEG) {
      minWallNormalF = Math.min(minWallNormalF, totalWheelNormalF);
      if (totalWheelNormalF < 50 && distToRamp > 0.72) {
        phase = "FELL_OFF_RAMP";
      }
    }

    const perNozzleMax = totalThrusterN * 0.22;
    for (const [k, frac] of Object.entries(thrust)) {
      if (frac > 0.001 && perNozzleMax > 0) {
        const nz = nozzles[k];
        const fMag = Math.min(1, frac) * perNozzleMax;
        const fBody = [nz.fDir[0] * fMag, nz.fDir[1] * fMag, nz.fDir[2] * fMag];
        const fWorld = quatRotate(quat, fBody);
        F[0] += fWorld[0]; F[1] += fWorld[1]; F[2] += fWorld[2];
        const tNz = cross(nz.r, fBody);
        tauBody[0] += tNz[0]; tauBody[1] += tNz[1]; tauBody[2] += tNz[2];
      }
    }

    // Chassis collision with ground/ramp
    const chassisR = 0.36;
    if (pos[1] < chassisR) {
      const pen = chassisR - pos[1];
      const impactVn = -vel[1];
      if (impactVn > 4.2 || yAxis[1] < 0.35) {
        maxImpactImpulse = Math.max(maxImpactImpulse, Math.max(impactVn, 3.5) * mass * (yAxis[1] < 0.35 ? 1.2 : 0.65));
      }
      const fnChassis = mass * 95 * pen + Math.max(0, -vel[1]) * mass * 14;
      F[1] += fnChassis;
      F[0] -= vel[0] * mass * 3.5;
    }

    vel[0] += (F[0] / mass) * dt;
    vel[1] += (F[1] / mass) * dt;
    vel[2] += (F[2] / mass) * dt;
    pos[0] += vel[0] * dt;
    pos[1] += vel[1] * dt;
    pos[2] += vel[2] * dt;

    const Iw = [Ibody[0]*omegaBody[0], Ibody[1]*omegaBody[1], Ibody[2]*omegaBody[2]];
    const gyro = cross(omegaBody, Iw);
    omegaBody[0] += ((tauBody[0] - gyro[0]) / Ibody[0]) * dt;
    omegaBody[1] += ((tauBody[1] - gyro[1]) / Ibody[1]) * dt;
    omegaBody[2] += ((tauBody[2] - gyro[2]) / Ibody[2]) * dt;
    omegaBody[0] *= 0.995;
    omegaBody[1] *= 0.992;
    omegaBody[2] *= 0.995;

    const dq = quatMul(quat, [omegaBody[0]*0.5*dt, omegaBody[1]*0.5*dt, omegaBody[2]*0.5*dt, 0]);
    quat = quatNormalize([quat[0]+dq[0], quat[1]+dq[1], quat[2]+dq[2], quat[3]+dq[3]]);

    if (verbose && (step % 60 === 0)) {
      console.log(`t=${t.toFixed(2)}s [${phase}] pos=(${pos[0].toFixed(1)}, ${pos[1].toFixed(1)}) vel=(${vel[0].toFixed(1)}, ${vel[1].toFixed(1)}) yUp=${yAxis[1].toFixed(2)} xAxis=(${xAxis[0].toFixed(2)},${xAxis[1].toFixed(2)})`);
    }
  }
  console.log("Summary:", { phase, maxImpactImpulse: Math.round(maxImpactImpulse), minWallNormalF: Math.round(minWallNormalF), finalPos: pos.map(v => +v.toFixed(2)) });
}

console.log("=== 1. DEFAULT STUNT ===");
runSim({}, true);
console.log("=== 2. LOW DOWNFORCE ===");
runSim({ maxFanKgf: 750 }, false);
console.log("=== 3. THRUSTER FAILURE ===");
runSim({ thrusterKN: 0 }, false);
console.log("=== 4. TOO SLOW ===");
runSim({ drivePower: 0.35 }, false);
'

args.command:
node -e '
const DEG = Math.PI / 180;
const RAD = 180 / Math.PI;
const LIP_ANGLE = 115 * DEG;

class RampCurve {
  constructor() {
    this.N = 500;
    this.sArr = new Float64Array(this.N + 1);
    this.xArr = new Float64Array(this.N + 1);
    this.yArr = new Float64Array(this.N + 1);
    this.thArr = new Float64Array(this.N + 1);
    this.kArr = new Float64Array(this.N + 1);
    const rawX = [0], rawY = [0], rawTh = [0];
    for (let i = 1; i <= this.N; i++) {
      const u = i / this.N;
      const th = LIP_ANGLE * (1.42 * Math.pow(u, 1.55) - 0.42 * Math.pow(u, 2.55));
      rawTh.push(th);
      const du = 1 / this.N;
      const thMid = 0.5 * (rawTh[i - 1] + th);
      rawX.push(rawX[i - 1] + Math.cos(thMid) * du);
      rawY.push(rawY[i - 1] + Math.sin(thMid) * du);
    }
    this.L = 20.0 / rawY[this.N];
    this.width = 5.4;
    for (let i = 0; i <= this.N; i++) {
      const u = i / this.N;
      this.sArr[i] = u * this.L;
      this.xArr[i] = rawX[i] * this.L;
      this.yArr[i] = rawY[i] * this.L;
      this.thArr[i] = rawTh[i];
      const dth_du = LIP_ANGLE * (1.42 * 1.55 * Math.pow(Math.max(u, 1e-4), 0.55) - 0.42 * 2.55 * Math.pow(u, 1.55));
      this.kArr[i] = (i === 0) ? 0 : dth_du / this.L;
    }
  }
  sample(s) {
    if (s <= 0) {
      return { s, x: s, y: 0, theta: 0, kappa: 0, tx: 1, ty: 0, nx: 0, ny: 1 };
    }
    const sc = Math.min(this.L, s);
    const u = sc / this.L;
    const idx = u * this.N;
    const i0 = Math.min(this.N - 1, Math.floor(idx));
    const f = idx - i0;
    const x = this.xArr[i0] + (this.xArr[i0 + 1] - this.xArr[i0]) * f;
    const y = this.yArr[i0] + (this.yArr[i0 + 1] - this.yArr[i0]) * f;
    const th = this.thArr[i0] + (this.thArr[i0 + 1] - this.thArr[i0]) * f;
    const k = this.kArr[i0] + (this.kArr[i0 + 1] - this.kArr[i0]) * f;
    return {
      s: sc, x, y, theta: th, kappa: k,
      tx: Math.cos(th), ty: Math.sin(th),
      nx: -Math.sin(th), ny: Math.cos(th)
    };
  }
  closestRampPoint(px, py) {
    let bestS = 0, bestD2 = Infinity;
    for (let i = 0; i <= this.N; i += 4) {
      const dx = px - this.xArr[i];
      const dy = py - this.yArr[i];
      const d2 = dx * dx + dy * dy;
      if (d2 < bestD2) { bestD2 = d2; bestS = this.sArr[i]; }
    }
    for (let iter = 0; iter < 4; iter++) {
      const pt = this.sample(bestS);
      const dx = px - pt.x, dy = py - pt.y;
      const ds = dx * pt.tx + dy * pt.ty;
      bestS = Math.max(0, Math.min(this.L, bestS + ds));
    }
    return this.sample(bestS);
  }
}

function quatRotate(q, v) {
  const x = v[0], y = v[1], z = v[2];
  const qx = q[0], qy = q[1], qz = q[2], qw = q[3];
  const ix = qw * x + qy * z - qz * y;
  const iy = qw * y + qz * x - qx * z;
  const iz = qw * z + qx * y - qy * x;
  const iw = -qx * x - qy * y - qz * z;
  return [
    ix * qw + iw * -qx + iy * -qz - iz * -qy,
    iy * qw + iw * -qy + iz * -qx - ix * -qz,
    iz * qw + iw * -qz + ix * -qy - iy * -qx
  ];
}
function quatConj(q) { return [-q[0], -q[1], -q[2], q[3]]; }
function quatMul(a, b) {
  return [
    a[3]*b[0] + a[0]*b[3] + a[1]*b[2] - a[2]*b[1],
    a[3]*b[1] - a[0]*b[2] + a[1]*b[3] + a[2]*b[0],
    a[3]*b[2] + a[0]*b[1] - a[1]*b[0] + a[2]*b[3],
    a[3]*b[3] - a[0]*b[0] - a[1]*b[1] - a[2]*b[2]
  ];
}
function quatNormalize(q) {
  const l = Math.hypot(q[0], q[1], q[2], q[3]) || 1;
  return [q[0]/l, q[1]/l, q[2]/l, q[3]/l];
}
function cross(a, b) {
  return [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]];
}
function dot(a, b) { return a[0]*b[0]+a[1]*b[1]+a[2]*b[2]; }

const ramp = new RampCurve();

function runSim(cfg, verbose = true) {
  const mass = cfg.mass ?? 2000;
  const maxFanKgf = cfg.maxFanKgf ?? 4700;
  const drivePowerScale = cfg.drivePower ?? 1.0;
  const totalThrusterN = (cfg.thrusterKN ?? 72) * 1000;
  const g = cfg.gravity ?? 9.81;

  const Ibody = [mass * 0.55, mass * 1.95, mass * 1.85];

  let pos = [-5.0, 0.42, 0];
  let vel = [0, 0, 0];
  let quat = [0, 0, 0, 1];
  let omegaBody = [0, 0, 0];

  const wheels = [
    { name: "FL", r: [ 1.42, -0.06, -0.84], comp: 0.08 },
    { name: "FR", r: [ 1.42, -0.06,  0.84], comp: 0.08 },
    { name: "RL", r: [-1.42, -0.06, -0.84], comp: 0.08 },
    { name: "RR", r: [-1.42, -0.06,  0.84], comp: 0.08 }
  ];

  const nozzles = {
    LIFT_FL:   { r: [ 1.35, -0.30, -0.78], fDir: [ 0.0,  1.0,  0.0] },
    LIFT_FR:   { r: [ 1.35, -0.30,  0.78], fDir: [ 0.0,  1.0,  0.0] },
    LIFT_RL:   { r: [-1.35, -0.30, -0.78], fDir: [ 0.0,  1.0,  0.0] },
    LIFT_RR:   { r: [-1.35, -0.30,  0.78], fDir: [ 0.0,  1.0,  0.0] },
    ROLL_L:    { r: [ 0.05, -0.25, -0.95], fDir: [ 0.0,  0.90, -0.43] },
    ROLL_R:    { r: [ 0.05,  0.25,  0.95], fDir: [ 0.0, -0.90,  0.43] },
    PITCH_NOSE:{ r: [ 1.90, -0.22,  0.00], fDir: [ 0.0,  1.0,  0.0] },
    PITCH_TAIL:{ r: [-1.95, -0.22,  0.00], fDir: [ 0.25, 0.968, 0.0] },
    REAR_L:    { r: [-2.22, -0.10, -0.30], fDir: [ 1.0,  0.0,  0.0] },
    REAR_R:    { r: [-2.22, -0.10,  0.30], fDir: [ 1.0,  0.0,  0.0] }
  };

  let phase = "READY";
  let holdTimer = 0;
  let releaseTimer = 0;
  let landTimer = 0;
  let maxImpactImpulse = 0;
  let minWallNormalF = Infinity;
  let maxPeakHeight = 0;

  const dt = 1 / 120;
  for (let step = 0; step < 120 * 17; step++) {
    const t = step * dt;
    const xAxis = quatRotate(quat, [1, 0, 0]);
    const yAxis = quatRotate(quat, [0, 1, 0]);
    const zAxis = quatRotate(quat, [0, 0, 1]);
    maxPeakHeight = Math.max(maxPeakHeight, pos[1]);

    const rp = ramp.closestRampPoint(pos[0], pos[1]);
    const distToRamp = (pos[0] - rp.x) * rp.nx + (pos[1] - rp.y) * rp.ny;
    const onRampRange = (pos[0] > -0.5 && rp.s <= ramp.L && Math.abs(pos[2]) < 2.6 && distToRamp > -0.2 && distToRamp < 1.5);

    let driveForceCmd = 0;
    let brakeCmd = 0;
    let fanThrottle = 0;
    const thrust = { LIFT_FL:0, LIFT_FR:0, LIFT_RL:0, LIFT_RR:0, ROLL_L:0, ROLL_R:0, PITCH_NOSE:0, PITCH_TAIL:0, REAR_L:0, REAR_R:0 };

    const maxMotorForce = 30000 * drivePowerScale;

    if (phase === "READY") {
      brakeCmd = 1.0;
      if (t >= 0.7) phase = "CLIMB";
    } else if (phase === "CLIMB") {
      fanThrottle = rp.theta > 0.12 ? 1.0 : Math.min(1.0, Math.max(0.2, (pos[0] + 4) * 0.2));
      const targetS = ramp.L - 1.55; // theta ~ 113.5 deg, y ~ 18.9 m
      const remS = targetS - rp.s;
      const tangVel = vel[0] * rp.tx + vel[1] * rp.ty;
      // Cruise climb speed ~ 9.5 m/s so climb takes ~4.5 seconds (matching clip 2s -> 6.8s)
      const vCruise = 9.6 * drivePowerScale;
      const vApproach = Math.sqrt(Math.max(0, 2 * 4.5 * Math.max(0, remS)));
      const vTarget = Math.min(vCruise, vApproach);

      if (remS <= 0.35 && Math.abs(tangVel) < 1.2 && rp.theta > 108 * DEG && distToRamp < 0.65) {
        phase = "HOLD_INVERTED";
        holdTimer = 0;
      } else if (t > 2.5 && tangVel < -0.8 && rp.s < targetS - 2.0) {
        phase = "STALLED_ON_RAMP";
      } else {
