        if (wxErr > 0) {
          const u = Math.min(1.0, wxErr * 0.45);
          thrust.ROLL_L = u;
          thrust.ROLL_R_INV = u;
        } else {
          const u = Math.min(1.0, -wxErr * 0.45);
          thrust.ROLL_R = u;
          thrust.ROLL_L_INV = u;
        }

