  let quat = [0, 0, 0, 1];
  let omegaBody = [0, 0, 0];

  const wheels = [
    { name: "wheelFL", r: [ 1.42, -0.06, -0.84], comp: 0.08 },
    { name: "wheelFR", r: [ 1.42, -0.06,  0.84], comp: 0.08 },
    { name: "wheelRL", r: [-1.42, -0.06, -0.84], comp: 0.08 },
    { name: "wheelRR", r: [-1.42, -0.06,  0.84], comp: 0.08 }
  ];

