}
function cross(a, b) { return [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]]; }
function dot(a, b) { return a[0]*b[0]+a[1]*b[1]+a[2]*b[2]; }

const ramp = new RampCurve();

function runSim(cfg) {
  const mass = cfg.mass ?? 2000;
  const maxFanKgf = cfg.maxFanKgf ?? 4700;
  const drivePowerScale = cfg.drivePower ?? 1.0;
  const totalThrusterN = (cfg.thrusterKN ?? 72) * 1000;
  const g = cfg.gravity ?? 9.81;

  const Ibody = [mass * 0.42, mass * 1.85, mass * 1.65];

  let pos = [-5.0, 0.42, 0];
  let vel = [0, 0, 0];
  let quat = [0, 0, 0, 1];
  let omegaBody = [0, 0, 0];

  const wheels = [
    { name: "wheelFL", r: [ 1.42, -0.06, -0.84], comp: 0.08 },
    { name: "wheelFR", r: [ 1.42, -0.06,  0.84], comp: 0.08 },
    { name: "wheelRL", r: [-1.42, -0.06, -0.84], comp: 0.08 },
    { name: "wheelRR", r: [-1.42, -0.06,  0.84], comp: 0.08 }
  ];

  const hullNodes = [
    { part: "frontBumper", r: [ 2.15, -0.04, -0.75], thresh: 5.2 },
    { part: "frontBumper", r: [ 2.15, -0.04,  0.75], thresh: 5.2 },
    { part: "hood",        r: [ 1.60,  0.24,  0.00], thresh: 5.2 },
    { part: "frontSection",r: [ 1.40, -0.14,  0.00], thresh: 6.5 },
    { part: "canopyGlass", r: [ 0.35,  0.58, -0.52], thresh: 3.8 },
    { part: "canopyGlass", r: [ 0.35,  0.58,  0.52], thresh: 3.8 },
    { part: "canopyGlass", r: [-0.65,  0.55,  0.00], thresh: 3.8 },
    { part: "leftDoor",    r: [ 0.00,  0.08, -0.98], thresh: 5.0 },
    { part: "rightDoor",   r: [ 0.00,  0.08,  0.98], thresh: 5.0 },
    { part: "rearSection", r: [-1.40, -0.14,  0.00], thresh: 6.5 },
    { part: "rearBumper",  r: [-2.15, -0.02, -0.75], thresh: 5.2 },
    { part: "rearBumper",  r: [-2.15, -0.02,  0.75], thresh: 5.2 }
  ];
  const brokenParts = new Set();

  const nozzles = {
    LIFT_FL:   { r: [ 1.35, -0.30, -0.78], fDir: [ 0.0,  1.0,  0.0], scale: 0.22 },
    LIFT_FR:   { r: [ 1.35, -0.30,  0.78], fDir: [ 0.0,  1.0,  0.0], scale: 0.22 },
    LIFT_RL:   { r: [-1.35, -0.30, -0.78], fDir: [ 0.0,  1.0,  0.0], scale: 0.22 },
    LIFT_RR:   { r: [-1.35, -0.30,  0.78], fDir: [ 0.0,  1.0,  0.0], scale: 0.22 },
    ROLL_L:    { r: [ 0.00, -0.25, -0.96], fDir: [ 0.0,  0.94,  0.34], scale: 0.26 },
    ROLL_R:    { r: [ 0.00, -0.25,  0.96], fDir: [ 0.0,  0.94, -0.34], scale: 0.26 },
    ROLL_L_INV:{ r: [ 0.00,  0.25, -0.96], fDir: [ 0.0, -0.94,  0.34], scale: 0.26 },
    ROLL_R_INV:{ r: [ 0.00,  0.25,  0.96], fDir: [ 0.0, -0.94, -0.34], scale: 0.26 },
    PITCH_NOSE:{ r: [ 1.95, -0.22,  0.00], fDir: [ 0.0,  1.0,  0.0], scale: 0.22 },
    PITCH_TAIL:{ r: [-1.95, -0.22,  0.00], fDir: [ 0.0,  1.0,  0.0], scale: 0.22 },
    PITCH_NOSE_DOWN:{ r: [ 1.95,  0.22,  0.00], fDir: [ 0.0, -1.0,  0.0], scale: 0.22 },
    PITCH_TAIL_DOWN:{ r: [-1.95,  0.22,  0.00], fDir: [ 0.0, -1.0,  0.0], scale: 0.22 },
    REAR_L:    { r: [-2.22, -0.10, -0.42], fDir: [ 1.0,  0.0,  0.0], scale: 0.18 },
    REAR_R:    { r: [-2.22, -0.10,  0.42], fDir: [ 1.0,  0.0,  0.0], scale: 0.18 }
  };

  let phase = "READY";
  let holdTimer = 0, releaseTimer = 0, hoverTimer = 0, landTimer = 0;
  let maxPeakHeight = 0;

  const dt = 1 / 120;
  for (let step = 0; step < 120 * 16; step++) {
    const t = step * dt;
    const xAxis = quatRotate(quat, [1, 0, 0]);
    const yAxis = quatRotate(quat, [0, 1, 0]);
    const zAxis = quatRotate(quat, [0, 0, 1]);
    maxPeakHeight = Math.max(maxPeakHeight, pos[1]);

    const rp = ramp.closestRampPoint(pos[0], pos[1]);
    const distToRamp = (pos[0] - rp.x) * rp.nx + (pos[1] - rp.y) * rp.ny;
    const onRampRange = (pos[0] > -0.5 && rp.s <= ramp.L && Math.abs(pos[2]) < 2.65 && distToRamp > -0.2 && distToRamp < 1.35);

    let driveForceCmd = 0, brakeCmd = 0, steerTorque = 0, fanThrottle = 0;
    const thrust = {};
    for (const k of Object.keys(nozzles)) thrust[k] = 0;

    // Max wheel drive force scales with drivePowerScale^1.6
    const maxMotorForce = 30000 * Math.pow(drivePowerScale, 1.4);

    if (brokenParts.size > 0) {
      phase = "CRASHED";
      fanThrottle = 0;
      brakeCmd = 0.4;
    } else if (phase === "READY") {
      brakeCmd = 1.0;
      if (t >= 0.7) phase = "CLIMB";
    } else if (phase === "CLIMB") {
      fanThrottle = rp.theta > 0.12 ? 1.0 : Math.min(1.0, Math.max(0.2, (pos[0] + 4) * 0.2));
      const targetS = ramp.L - 1.55;
      const remS = targetS - rp.s;
      const tangVel = vel[0] * rp.tx + vel[1] * rp.ty;
      const vCruise = 9.8 * drivePowerScale;
      const vApproach = Math.sqrt(Math.max(0, 2 * 4.5 * Math.max(0, remS)));
      const vTarget = Math.min(vCruise, vApproach);

      if (remS <= 0.35 && Math.abs(tangVel) < 1.2 && rp.theta > 108 * DEG && distToRamp < 0.65) {
        phase = "HOLD_INVERTED";
        holdTimer = 0;
      } else if (t > 2.4 && tangVel < -0.35 && rp.s < targetS - 1.5) {
        phase = "STALLED_ON_RAMP";
      } else {
        const gravComp = mass * g * Math.sin(rp.theta);
        const vErr = vTarget - tangVel;
        const rawCmd = gravComp + vErr * (mass * 4.2);
        if (rawCmd >= 0) {
          driveForceCmd = Math.min(maxMotorForce, rawCmd);
        } else {
          brakeCmd = Math.min(1.0, -rawCmd / (mass * 10));
        }
      }
    } else if (phase === "STALLED_ON_RAMP") {
      // Stalled on vertical wall: airflow separation cuts fan suction, car peels/slides off ramp!
      fanThrottle = 0.0;
      brakeCmd = 0.0;
    } else if (phase === "HOLD_INVERTED") {
      fanThrottle = 1.0;
      brakeCmd = 1.0;
      holdTimer += dt;
      const targetS = ramp.L - 1.50;
      const sErr = targetS - rp.s;
      const tangVel = vel[0] * rp.tx + vel[1] * rp.ty;
      const gravComp = mass * g * Math.sin(rp.theta);
      driveForceCmd = Math.max(-maxMotorForce, Math.min(maxMotorForce, gravComp + sErr * 24000 - tangVel * 24000));
      if (holdTimer > 1.75) thrust.PITCH_NOSE = 0.25;
      if (holdTimer >= 2.0) {
        phase = "RELEASE_AND_ROLL";
        releaseTimer = 0;
      }
    } else if (phase === "RELEASE_AND_ROLL") {
      releaseTimer += dt;
      fanThrottle = 0;

      if (releaseTimer < 0.28) {
        thrust.PITCH_NOSE = 0.95;
        thrust.PITCH_TAIL_DOWN = 0.85;
        thrust.REAR_L = 0.80;
        thrust.REAR_R = 0.80;
      } else {
        const by = -yAxis[0];
        const bz = -zAxis[0];
        const targetWz = by * 5.0;
        const wzErr = targetWz - omegaBody[2];
        if (wzErr > 0) {
          thrust.PITCH_NOSE = Math.min(0.9, wzErr * 0.35);
          thrust.PITCH_TAIL_DOWN = Math.min(0.9, wzErr * 0.35);
        } else {
          thrust.PITCH_TAIL = Math.min(0.9, -wzErr * 0.35);
          thrust.PITCH_NOSE_DOWN = Math.min(0.9, -wzErr * 0.35);
        }

        const targetWy = -bz * 4.5;
        const wyErr = targetWy - omegaBody[1];

        let phi = Math.atan2(zAxis[1], yAxis[1]);
        if (yAxis[1] < -0.15 && Math.abs(phi) > 2.1) phi = Math.PI;
        const targetWx = Math.max(-6.0, Math.min(6.0, phi * 4.8));
        const wxErr = targetWx - omegaBody[0];
        if (wxErr > 0) {
          const u = Math.min(1.0, wxErr * 0.45);
          thrust.ROLL_L = u;
          thrust.ROLL_R_INV = u;
        } else {
          const u = Math.min(1.0, -wxErr * 0.45);
          thrust.ROLL_R = u;
          thrust.ROLL_L_INV = u;
        }

        const baseRear = (pos[0] > -4.0 && vel[0] > -5.5 && xAxis[0] < -0.6) ? 0.55 : 0.1;
        thrust.REAR_L = Math.max(0, Math.min(1, baseRear - wyErr * 0.3));
        thrust.REAR_R = Math.max(0, Math.min(1, baseRear + wyErr * 0.3));

        if (yAxis[1] > 0.45) {
          let targetVy = -1.2;
          if (pos[1] > 2.4) {
            targetVy = -Math.min(10.5, Math.sqrt(2 * 6.2 * (pos[1] - 1.75)) + 0.6);
          } else {
            hoverTimer += dt;
            if (hoverTimer < 0.55) {
              targetVy = (1.65 - pos[1]) * 3.0;
            } else {
              targetVy = -1.05;
            }
          }
          const vyErr = targetVy - vel[1];
          const neededUpForce = Math.max(0, mass * (g + vyErr * 6.5) / Math.max(0.55, yAxis[1]));
          const perCornerMax = totalThrusterN * 0.22;
          const baseLift = perCornerMax > 0 ? Math.min(1.0, neededUpForce / (4 * perCornerMax)) : 0;
          const pitchTrim = Math.max(-0.25, Math.min(0.25, wzErr * 0.12));
          const rollTrim = Math.max(-0.25, Math.min(0.25, wxErr * 0.12));
          thrust.LIFT_FL = Math.max(0, Math.min(1, baseLift + pitchTrim + rollTrim));
          thrust.LIFT_FR = Math.max(0, Math.min(1, baseLift + pitchTrim - rollTrim));
          thrust.LIFT_RL = Math.max(0, Math.min(1, baseLift - pitchTrim + rollTrim));
          thrust.LIFT_RR = Math.max(0, Math.min(1, baseLift - pitchTrim - rollTrim));
        }
      }

      if (pos[1] <= 0.45 && yAxis[1] > 0.90 && releaseTimer > 1.2) {
        phase = "DRIVE_OUT";
        landTimer = 0;
      }
    } else if (phase === "DRIVE_OUT") {
      landTimer += dt;
      fanThrottle = 0.25;
      if (landTimer < 1.55) {
        driveForceCmd = 14000;
      } else {
        brakeCmd = 1.2;
        if (Math.hypot(vel[0], vel[2]) < 0.25 && landTimer > 2.0) phase = "COMPLETE";
      }
    } else if (phase === "COMPLETE") {
      brakeCmd = 1.5;
    }

    let F = [0, -mass * g, 0];
    let tauBody = [0, steerTorque, 0];

    const speed = Math.hypot(vel[0], vel[1], vel[2]);
    const drag = 0.42 * speed;
    F[0] -= drag * vel[0]; F[1] -= drag * vel[1]; F[2] -= drag * vel[2];

    let surfaceDist = pos[1] - 0.38;
    if (onRampRange && (pos[0] > 0 || rp.s > 0.05)) {
      surfaceDist = distToRamp - 0.38;
    }
    const fanProx = Math.max(0, Math.min(1, (0.90 - surfaceDist) / 0.75));
    const fanForceMag = fanThrottle * (maxFanKgf * 9.81) * (fanProx * fanProx);
    F[0] -= yAxis[0] * fanForceMag;
    F[1] -= yAxis[1] * fanForceMag;
    F[2] -= yAxis[2] * fanForceMag;
    tauBody[2] += 0.06 * fanForceMag;

    const kSpring = mass * 36;
    const kDamp = mass * 5.5;

    for (let w of wheels) {
      if (brokenParts.has(w.name)) continue;
      const wPos = [
        pos[0] + xAxis[0]*w.r[0] + yAxis[0]*w.r[1] + zAxis[0]*w.r[2],
        pos[1] + xAxis[1]*w.r[0] + yAxis[1]*w.r[1] + zAxis[1]*w.r[2],
        pos[2] + xAxis[2]*w.r[0] + yAxis[2]*w.r[1] + zAxis[2]*w.r[2]
      ];
      const wRotVel = quatRotate(quat, cross(omegaBody, w.r));
      const wVel = [vel[0] + wRotVel[0], vel[1] + wRotVel[1], vel[2] + wRotVel[2]];

      const wrp = ramp.closestRampPoint(wPos[0], wPos[1]);
      const dRamp = (wPos[0] - wrp.x) * wrp.nx + (wPos[1] - wrp.y) * wrp.ny;
      const dGround = wPos[1];
      let dSurf = dGround, n = [0, 1, 0];
      if (wPos[0] > 0.05 && wrp.s > 0 && wrp.s <= ramp.L && Math.abs(wPos[2]) < 2.65 && dRamp > -0.25 && dRamp < 1.1) {
        if (wPos[1] > 0.6 || dRamp < dGround) {
          dSurf = dRamp;
          n = [wrp.nx, wrp.ny, 0];
        }
      }
      const restDist = 0.42;
      const align = dot(yAxis, n);
      if (dSurf < restDist && align > 0.25) {
        const comp = restDist - dSurf;
        w.comp = Math.min(0.28, comp);
        const vn = dot(wVel, n);
        const Fn = Math.max(0, kSpring * comp - kDamp * vn);
        if (-vn > 6.5) brokenParts.add(w.name);

        let tLong = [
          xAxis[0] - dot(xAxis, n)*n[0],
          xAxis[1] - dot(xAxis, n)*n[1],
          xAxis[2] - dot(xAxis, n)*n[2]
        ];
        const tlLen = Math.hypot(tLong[0], tLong[1], tLong[2]) || 1;
        tLong = [tLong[0]/tlLen, tLong[1]/tlLen, tLong[2]/tlLen];

        let tLat = cross(n, tLong);
        const vLong = dot(wVel, tLong);
        const vLat = dot(wVel, tLat);

        let fLong = (driveForceCmd * 0.25) - brakeCmd * vLong * (mass * 4.5);
        let fLat = -vLat * (mass * 6.0) - (phase === "STALLED_ON_RAMP" ? 0 : wPos[2] * (mass * 2.5));

        const maxGrip = 0.95 * Fn;
        const fTangMag = Math.hypot(fLong, fLat);
        if (fTangMag > maxGrip && fTangMag > 1e-5) {
          fLong *= maxGrip / fTangMag;
          fLat *= maxGrip / fTangMag;
        }

        const Fw = [
          n[0]*Fn + tLong[0]*fLong + tLat[0]*fLat,
          n[1]*Fn + tLong[1]*fLong + tLat[1]*fLat,
          n[2]*Fn + tLong[2]*fLong + tLat[2]*fLat
        ];
        F[0] += Fw[0]; F[1] += Fw[1]; F[2] += Fw[2];
        const FwBody = quatRotate(quatConj(quat), Fw);
        const rPatch = [w.r[0], -0.34, w.r[2]];
        const tW = cross(rPatch, FwBody);
        tauBody[0] += tW[0]; tauBody[1] += tW[1]; tauBody[2] += tW[2];
      } else {
        w.comp = 0;
        if (dSurf < 0.15) {
          const vn = dot(wVel, n);
          if (-vn > 3.8) brokenParts.add(w.name);
        }
      }
    }

    for (const [k, frac] of Object.entries(thrust)) {
      if (frac > 0.001 && totalThrusterN > 0) {
        const nz = nozzles[k];
        const fMag = Math.min(1, frac) * (totalThrusterN * nz.scale);
        const fBody = [nz.fDir[0] * fMag, nz.fDir[1] * fMag, nz.fDir[2] * fMag];
        const fWorld = quatRotate(quat, fBody);
        F[0] += fWorld[0]; F[1] += fWorld[1]; F[2] += fWorld[2];
        const tNz = cross(nz.r, fBody);
        tauBody[0] += tNz[0]; tauBody[1] += tNz[1]; tauBody[2] += tNz[2];
      }
    }

    // Check hull structural nodes against ground (y = 0) and ramp surface (dRamp < 0.02)
    for (const node of hullNodes) {
      const nPos = [
        pos[0] + xAxis[0]*node.r[0] + yAxis[0]*node.r[1] + zAxis[0]*node.r[2],
        pos[1] + xAxis[1]*node.r[0] + yAxis[1]*node.r[1] + zAxis[1]*node.r[2],
        pos[2] + xAxis[2]*node.r[0] + yAxis[2]*node.r[1] + zAxis[2]*node.r[2]
      ];
      const nRotVel = quatRotate(quat, cross(omegaBody, node.r));
      const nVel = [vel[0] + nRotVel[0], vel[1] + nRotVel[1], vel[2] + nRotVel[2]];

      // Ground contact
      if (nPos[1] < 0.03) {
        const pen = 0.03 - nPos[1];
        const impactSpd = Math.hypot(nVel[1], nVel[0]*0.5, nVel[2]*0.5);
        if (-nVel[1] > node.thresh || (yAxis[1] < 0.5 && impactSpd > node.thresh * 0.65)) {
          brokenParts.add(node.part);
          if (impactSpd > 6.5) {
            for (const h2 of hullNodes) brokenParts.add(h2.part);
            for (const w2 of wheels) brokenParts.add(w2.name);
          }
        }
        const fnNode = mass * 22 * pen + Math.max(0, -nVel[1]) * mass * 3.5;
        const Fnode = [-nVel[0]*mass*0.6, fnNode, -nVel[2]*mass*0.6];
        F[0] += Fnode[0]; F[1] += Fnode[1]; F[2] += Fnode[2];
        const tNode = cross(node.r, quatRotate(quatConj(quat), Fnode));
        tauBody[0] += tNode[0]; tauBody[1] += tNode[1]; tauBody[2] += tNode[2];
      }

      // Ramp surface contact (only actual penetration dRamp < 0.02!)
      const nrp = ramp.closestRampPoint(nPos[0], nPos[1]);
      const dRamp = (nPos[0] - nrp.x) * nrp.nx + (nPos[1] - nrp.y) * nrp.ny;
      if (nPos[0] > 0.2 && nrp.s > 0.5 && nrp.s <= ramp.L && Math.abs(nPos[2]) < 2.85 && dRamp < 0.02 && dRamp > -0.35) {
        const vn = nVel[0]*nrp.nx + nVel[1]*nrp.ny;
        const impactSpd = Math.hypot(nVel[0], nVel[1], nVel[2]);
        if (-vn > node.thresh * 0.7 || (dot(yAxis, [nrp.nx, nrp.ny, 0]) < 0.55 && impactSpd > 4.0) || (phase === "STALLED_ON_RAMP" && impactSpd > 4.5)) {
          brokenParts.add(node.part);
          if (impactSpd > 5.5) {
            for (const h2 of hullNodes) brokenParts.add(h2.part);
            for (const w2 of wheels) brokenParts.add(w2.name);
          }
        }
        const pen = 0.02 - dRamp;
        const fnNode = mass * 20 * pen + Math.max(0, -vn) * mass * 3.0;
        const Fnode = [nrp.nx * fnNode, nrp.ny * fnNode, 0];
        F[0] += Fnode[0]; F[1] += Fnode[1];
        const tNode = cross(node.r, quatRotate(quatConj(quat), Fnode));
        tauBody[0] += tNode[0]; tauBody[1] += tNode[1]; tauBody[2] += tNode[2];
      }
    }

    vel[0] += (F[0] / mass) * dt;
    vel[1] += (F[1] / mass) * dt;
    vel[2] += (F[2] / mass) * dt;
    pos[0] += vel[0] * dt;
    pos[1] += vel[1] * dt;
    pos[2] += vel[2] * dt;

    const Iw = [Ibody[0]*omegaBody[0], Ibody[1]*omegaBody[1], Ibody[2]*omegaBody[2]];
    const gyro = cross(omegaBody, Iw);
    omegaBody[0] += ((tauBody[0] - gyro[0]) / Ibody[0]) * dt;
    omegaBody[1] += ((tauBody[1] - gyro[1]) / Ibody[1]) * dt;
    omegaBody[2] += ((tauBody[2] - gyro[2]) / Ibody[2]) * dt;
    omegaBody[0] *= 0.995;
    omegaBody[1] *= 0.992;
    omegaBody[2] *= 0.995;

    const dq = quatMul(quat, [omegaBody[0]*0.5*dt, omegaBody[1]*0.5*dt, omegaBody[2]*0.5*dt, 0]);
    quat = quatNormalize([quat[0]+dq[0], quat[1]+dq[1], quat[2]+dq[2], quat[3]+dq[3]]);
  }
  console.log("Summary:", { phase, maxPeakHeight: +maxPeakHeight.toFixed(1), brokenCount: brokenParts.size, finalPos: pos.map(v => +v.toFixed(2)) });
}

console.log("1. DEFAULT:"); runSim({});
console.log("2. LOW DOWNFORCE:"); runSim({ maxFanKgf: 650 });
console.log("3. THRUSTER FAILURE:"); runSim({ thrusterKN: 0 });
console.log("4. TOO SLOW:"); runSim({ drivePower: 0.52 });
