        const tNode = cross(node.r, quatRotate(quatConj(quat), Fnode));
        tauBody[0] += tNode[0]; tauBody[1] += tNode[1]; tauBody[2] += tNode[2];
      }

      const nrp = ramp.closestRampPoint(nPos[0], nPos[1]);
      const dRamp = (nPos[0] - nrp.x) * nrp.nx + (nPos[1] - nrp.y) * nrp.ny;
      if (nPos[0] > 0.2 && nrp.s > 0.5 && nrp.s <= ramp.L && Math.abs(nPos[2]) < 2.85 && dRamp < 0.02 && dRamp > -0.35) {
        const vn = nVel[0]*nrp.nx + nVel[1]*nrp.ny;
        const impactSpd = Math.hypot(nVel[0], nVel[1], nVel[2]);
        if (-vn > node.thresh * 0.7 || (dot(yAxis, [nrp.nx, nrp.ny, 0]) < 0.55 && impactSpd > 3.8)) {
          brokenParts.add(node.part);
          if (impactSpd > 5.0) {
            for (const h2 of hullNodes) brokenParts.add(h2.part);
            for (const w2 of wheels) brokenParts.add(w2.name);
          }
        }
        const pen = 0.02 - dRamp;
        const fnNode = mass * 20 * pen + Math.max(0, -vn) * mass * 3.0;
        const Fnode = [nrp.nx * fnNode, nrp.ny * fnNode, 0];
        F[0] += Fnode[0]; F[1] += Fnode[1];
        const tNode = cross(node.r, quatRotate(quatConj(quat), Fnode));
        tauBody[0] += tNode[0]; tauBody[1] += tNode[1]; tauBody[2] += tNode[2];
